nextflow_process {

    name "Test Process KAT_HIST"
    script "../main.nf"
    process "KAT_HIST"

    tag "modules"
    tag "modules_nfcore"
    tag "kat"
    tag "kat/hist"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('reads') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/merqury/merqury") }
            )
        }
    }
}
